const s = wb.getWorksheet('Sheet1');
const keep = s.getRange('C2:C73').getValues().map(r => String(r[0]));
log(keep.filter(v => v.includes('#N/A')).length, keep.length);
const del = [];
keep.forEach((v,i)=>{ if(!v.includes('#N/A')) del.push(i+2); });
// bottom-up contiguous blocks
const blocks = [];
for (const r of del) { const b = blocks[blocks.length-1]; if (b && b[1]===r-1) b[1]=r; else blocks.push([r,r]); }
log(JSON.stringify(blocks));
for (const [a,b] of blocks.reverse()) s.getRange(`${a}:${b}`).delete('row');
log(s.getUsedRange ? s.getUsedRange().getA1?.() : '');
s.getRange('A1:N8')

